using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayChargeTests
{
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayChargeTests()
    {
        _gateway = new Payments.PaymentGateway();
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCardAndAmount_ReturnsSuccessResult()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = 49.99m;

        // Act
        var result = await _gateway.ChargeAsync(cardToken, amount);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    [DataRow("tok_visa", 1.00)]
    [DataRow("tok_mastercard", 999.99)]
    [DataRow("tok_amex", 0.50)]
    public async Task ChargeAsync_VariousValidCards_ReturnsSuccess(string cardToken, double amount)
    {
        var result = await _gateway.ChargeAsync(cardToken, (decimal)amount);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.ChargeAsync(null!, 10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyCardToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(string.Empty, 10.00m));
    }

    [TestMethod]
    [DataRow(0.0)]
    [DataRow(-1.0)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_SuccessfulCharge_ReturnsNonEmptyChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 25.00m);

        Assert.IsNotNull(result.ChargeId);
        Assert.AreNotEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailureResult()
    {
        var result = await _gateway.ChargeAsync("tok_declined", 50.00m);

        Assert.IsFalse(result.Success);
    }
}

[TestClass]
public sealed class PaymentGatewayRefundTests
{
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayRefundTests()
    {
        _gateway = new Payments.PaymentGateway();
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        // Arrange
        var chargeId = "ch_valid_123";

        // Act
        var result = await _gateway.RefundAsync(chargeId);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(string.Empty));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailureResult()
    {
        var result = await _gateway.RefundAsync("ch_nonexistent_999");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_SuccessfulRefund_ReturnsNonEmptyRefundId()
    {
        var result = await _gateway.RefundAsync("ch_valid_123");

        Assert.IsNotNull(result.RefundId);
        Assert.AreNotEqual(string.Empty, result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefundedCharge_ReturnsFailure()
    {
        // First refund succeeds
        await _gateway.RefundAsync("ch_already_refunded");

        // Second refund on same charge should fail
        var result = await _gateway.RefundAsync("ch_already_refunded");

        Assert.IsFalse(result.Success);
    }
}

[TestClass]
public sealed class PaymentGatewayIntegrationTests
{
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayIntegrationTests()
    {
        _gateway = new Payments.PaymentGateway();
    }

    [TestMethod]
    public async Task ChargeAndRefund_FullWorkflow_BothSucceed()
    {
        // Charge
        var chargeResult = await _gateway.ChargeAsync("tok_valid_visa", 75.00m);
        Assert.IsTrue(chargeResult.Success);

        // Refund the charge
        var refundResult = await _gateway.RefundAsync(chargeResult.ChargeId);
        Assert.IsTrue(refundResult.Success);
        Assert.IsNotNull(refundResult.RefundId);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task ChargeAsync_CompletesWithinTimeout()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 10.00m);

        Assert.IsNotNull(result);
    }
}

